<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Scopes\Application\Usecase;

use Civi\Lughauth\Features\Oidc\Scopes\Domain\Gateway\ScopesConsentGateway;
use Civi\Lughauth\Features\Oidc\Scopes\Domain\ScopePermission;

final class ScopesConsentUsecase
{
    public function __construct(private readonly ScopesConsentGateway $gateway)
    {
    }

    /**
     * @return ScopePermission[]
     */
    public function pendingScopes(string $tenant, string $username, string $clientId, string $scope): array
    {
        $scopes = $this->normalizeScopes($scope);
        if (!$scopes) {
            return [];
        }

        return $this->gateway->pendingScopes($tenant, $username, $clientId, $scopes);
    }

    /**
     * @param string[] $scopes
     */
    public function storeAcceptedScopes(string $tenant, string $username, string $clientId, array $scopes): void
    {
        $scopes = $this->normalizeScopeList($scopes);
        $this->gateway->storeAcceptedScopes($tenant, $username, $clientId, $scopes);
    }

    /**
     * @return string[]
     */
    public function normalizeScopes(string $scope): array
    {
        if (trim($scope) === '') {
            return [];
        }

        $list = preg_split('/\s+/', trim($scope)) ?: [];
        $list = array_map(static fn (string $value): string => trim($value), $list);
        $list = array_filter($list, static fn (string $value): bool => $value !== '');
        return array_values(array_unique($list));
    }

    /**
     * @param string[] $scopes
     *
     * @return string[]
     */
    public function normalizeScopeList(array $scopes): array
    {
        $list = array_map(static fn (string $value): string => trim($value), $scopes);
        $list = array_filter($list, static fn (string $value): bool => $value !== '');
        return array_values(array_unique($list));
    }
}
